-- Slovenia deep-dive ES/DE/FR translations, completing 416 against the
-- English content in migration 416. This is a SEPARATE migration file,
-- so every translation row looks up its parent row via a JOIN on stable
-- identifying columns (country code / section / sort_order), never via
-- (SELECT MAX(id) ...). INSERT OR IGNORE throughout.

-- ==================== es ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Régimen de dos niveles: una obligación B2G ya consolidada a través del hub central de UJP, más una nueva ley B2B (ZIERDED) promulgada a fines de 2025 con un despliegue en dos etapas que culmina en 2027 y 2028', 'Esta página de análisis refleja la ley ZIERDED tal como se publicó en el Diario Oficial de Eslovenia y la orientación pública gubernamental disponible a inicios de agosto de 2026, y se ofrece a título informativo general, no como asesoría legal o tributaria. Confirme los requisitos vigentes directamente con FURS, UJP o un asesor fiscal/legal esloveno antes de basar en esta página sus decisiones de cumplimiento.', 'El sector público esloveno exige facturas electrónicas desde el 1 de enero de 2015 en virtud de la ZOPSPU/ZOPSPU-A, canalizadas a través del hub central EVIT de UJP. La facturación electrónica B2B no tuvo un mandato general hasta 2025, cuando el parlamento aprobó la ZIERDED (publicada en el Diario Oficial como Uradni list RS, št. 85/2025, del 6 de noviembre de 2025) -- la primera ley eslovena de facturación electrónica obligatoria entre empresas, con un régimen de proveedores certificados de vía electrónica que entra en vigor el 1 de abril de 2027 y la obligación central de intercambio a partir del 1 de enero de 2028.', 'Una factura conforme a la ZIERDED se intercambia a través de uno de tres canales permitidos -- un proveedor certificado de vía electrónica ("e-pot"), un enlace directo de sistema a sistema, o Peppol -- con el formato del estándar e-SLOG 2.0, la especificación nacional eslovena alineada con la norma EN 16931 y mantenida por la GZS (la Cámara de Comercio e Industria). Se trata de un modelo de intercambio descentralizado, no de una plataforma de clearance gubernamental: no existe un único portal gubernamental obligatorio para las facturas B2B, a diferencia del papel que cumple el portal e-Racuni de UJP para el sector público.', 'El mandato B2B se aplica de forma universal -- a toda entidad inscrita en el Registro Mercantil de Eslovenia y a toda persona autónoma, sin umbral de tamaño ni excepción escalonada alguna identificada en el texto de la ley. La facturación B2G se aplica a todo el sector público desde 2015. Se trata de una obligación B2B genuinamente nueva, no de la ampliación de una ya existente -- la mayoría de las empresas eslovenas no tienen actualmente ninguna obligación legal de intercambiar facturas electrónicas entre sí, y eso cambia el 1 de enero de 2028.', 'La mayoría de las empresas que leen esto no tienen actualmente ninguna obligación de facturación electrónica B2B en Eslovenia -- el trabajo pendiente consiste en elegir y probar con antelación uno de los tres canales de intercambio permitidos por la ZIERDED, bien antes de la fecha límite del 1 de enero de 2028, y no en reaccionar a algo que ya esté en vigor.', 'La ZIERDED respalda su mandato B2B con sanciones reales y específicas por artículo bajo el art. 24 (infracciones del intercambio central) y un rango independiente y más bajo bajo el art. 25 para las infracciones relativas a facturas de consumo -- ambos confirmados de forma independiente contra el texto del Diario Oficial en esta sesión, y no tomados de un resumen secundario.', 'Eslovenia exige que los organismos del sector público reciban facturas electrónicas desde el 1 de enero de 2015 (ZOPSPU/ZOPSPU-A, a través del hub central de UJP). Una nueva ley, la ZIERDED, añade el primer régimen esloveno de facturación electrónica B2B obligatoria: proveedores certificados de vía electrónica desde el 1 de abril de 2027, e intercambio obligatorio de facturas electrónicas para prácticamente todas las empresas y personas autónomas desde el 1 de enero de 2028, usando el estándar e-SLOG 2.0 sobre uno de tres canales permitidos, incluido Peppol.', '🇸🇮' FROM countries WHERE code = 'SI';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2015', 'El sector público queda obligado a recibir facturas electrónicas (ZOPSPU/ZOPSPU-A)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '6 nov 2025', 'La ZIERDED -- la primera ley eslovena de facturación electrónica B2B -- se publica en el Diario Oficial' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 abr 2027', 'Entra en vigor el régimen de proveedores certificados de vía electrónica' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1 ene 2028', 'Comienza el intercambio obligatorio de facturas electrónicas B2B' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'es', '1.000-3.000 €', 'Rango de multa central del art. 24 para personas jurídicas' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'Formato y canales', '[["Formato de factura B2B", "e-SLOG 2.0 -- el estándar XML propio de Eslovenia alineado con la norma EN 16931, mantenido por la GZS (Cámara de Comercio e Industria)"], ["Modelo de intercambio B2B", "Descentralizado -- no existe una única plataforma gubernamental obligatoria de clearance para el B2B, a diferencia del papel de UJP en el B2G"], ["Canales permitidos (ZIERDED, art. 9)", "Proveedor certificado de vía electrónica (\"e-pot\"); enlace directo de sistema a sistema; o Peppol"], ["Formato de factura B2G", "También e-SLOG, enviado a través del hub EVIT de UJP (bancos, procesadores contratados o el portal e-Racuni)"]]', 'La ZIERDED no designa una única red de transmisión obligatoria como sí hacen algunos países con modelo CTC -- las empresas eligen entre los tres canales permitidos, por lo que la elección del proveedor importa más en Eslovenia que en un régimen de plataforma única.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'El papel de UJP en el B2G', '[["Hub EVIT", "UJP opera la \"enotna vstopna in izstopna točka\" (punto único de entrada y salida) para el intercambio de facturas electrónicas de los usuarios presupuestarios"], ["Portal e-Racuni", "Vía de envío gratuita para proveedores sin banco ni procesador contratado -- https://eracuni.ujp.gov.si/"], ["Vías de banco / procesador", "Los bancos participantes y los procesadores de datos contratados por UJP también pueden transportar facturas electrónicas hacia los usuarios presupuestarios"], ["Estatus de Peppol Authority", "No establecido -- ninguna fuente confirma que Eslovenia tenga una Peppol Authority formalmente registrada ante OpenPeppol"]]', 'A veces se describe informalmente a UJP como la "Peppol Authority" de Eslovenia -- ese título no figura en la lista actual de autoridades propia de OpenPeppol, y la página gubernamental de UJP describe su papel como operador del hub EVIT, no como organismo de gobernanza de Peppol. Trate a UJP como el hub del B2G, no como una Peppol Authority confirmada, hasta que una fuente primaria indique lo contrario.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'A quién cubre la ZIERDED', '[["Alcance (art. 7)", "Toda entidad inscrita en el Registro Mercantil de Eslovenia, y toda persona autónoma"], ["Umbral de tamaño", "Ninguno identificado -- la ley se aplica de manera uniforme, sin ninguna excepción para pequeñas empresas identificada en el texto del Diario Oficial"], ["Facturas a consumidores", "Cubiertas por separado, bajo el rango de sanción más bajo del art. 25 en lugar del art. 24"], ["Sector público (B2G)", "Ya cubierto por separado desde 2015 bajo la ZOPSPU/ZOPSPU-A -- la ZIERDED es una incorporación centrada en el B2B, no un reemplazo"]]', 'El art. 1 de la ZIERDED vincula explícitamente la ley a la transposición de elementos de la directiva ViDA de la UE (2025/516) -- cabe esperar que se desarrollen más detalles (por ejemplo, cualquier futuro requisito de reporte digital) a medida que el propio pilar de facturación electrónica/reporte digital de ViDA se vaya implementando en toda la UE hacia 2030.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', 'El despliegue en dos etapas', '[["1 de abril de 2027", "Entra en vigor el régimen de proveedores certificados de vía electrónica del capítulo 4 de la ZIERDED -- los proveedores pueden solicitar la certificación y las empresas pueden empezar a usar proveedores certificados"], ["1 de enero de 2028", "La obligación central de intercambio obligatorio se aplica a todas las entidades comprendidas, en los tres canales permitidos"], ["Sin requisito de registro previo a 2027 identificado", "Nada en el texto del Diario Oficial exige que las empresas se registren o se preparen formalmente antes de la fecha de 2027"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '⚠️ Infracciones del intercambio central (art. 24)', NULL, NULL, 'El art. 24 de la ZIERDED establece el rango de sanción central por incumplir la obligación de intercambio B2B obligatorio una vez que resulte aplicable: 1.000-3.000 € para personas jurídicas, 500-1.500 € para empresarios individuales y 100-500 € para una persona responsable dentro de una organización. Estas cifras fueron confirmadas de forma independiente mediante consulta directa del texto del Diario Oficial en esta sesión, y no se tomaron de una fuente secundaria.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🧾 Infracciones relativas a facturas de consumo (art. 25)', NULL, NULL, 'Un rango de sanción independiente y más bajo se aplica específicamente a las infracciones relativas a facturas de consumo bajo el art. 25: 500-1.500 € para personas jurídicas, 100-500 € para empresarios individuales y 50-250 € para una persona responsable. Se trata de una categoría de infracción distinta de las multas centrales del intercambio B2B del art. 24, y no de una versión alternativa o reducida de la misma multa.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'es', '🔍 Lo que no pudimos confirmar', NULL, NULL, 'Los artículos sancionadores de la ZIERDED son legislación nueva -- todavía no existe un historial de aplicación al que remitirse como sí pueden hacerlo los análisis de Costa Rica o Jordania. Dos afirmaciones basadas únicamente en fuentes secundarias que a veces se repiten sobre el ecosistema esloveno de facturación electrónica -- que ZZI opera un "Exchange Hub" con marca formal, y que FURS ofrece una herramienta "miniBlagajna" utilizable en este contexto -- no fueron corroboradas de forma independiente en una página gubernamental primaria durante esta ronda de investigación, y se dejan deliberadamente fuera de esta página en lugar de repetirse como un hecho.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme su vía actual de facturación electrónica B2G, si vende a organismos públicos eslovenos', 'Compruebe si su empresa ya llega a los usuarios presupuestarios eslovenos a través de un banco, un procesador contratado por UJP, o el portal e-Racuni de UJP -- esta obligación se aplica desde 2015 y es independiente de la nueva ley B2B.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Lea el texto oficial de la ZIERDED antes de elegir un canal de intercambio B2B', 'La ley permite tres canales -- un proveedor certificado de vía electrónica, un enlace directo de sistema a sistema, o Peppol -- sin una única plataforma obligatoria; comprenda las ventajas y desventajas antes de comprometerse.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Confirme que su software de facturación pueda generar salidas conformes con e-SLOG 2.0 / EN 16931', 'e-SLOG 2.0 es el estándar nacional esloveno tanto para la obligación B2G ya existente como para la nueva ley B2B -- confirme que su proveedor lo admite, en lugar de dar por supuesto que basta con un soporte genérico de EN 16931.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Si opta por un proveedor certificado de vía electrónica, espere al régimen de certificación del 1 de abril de 2027 antes de elegir uno', 'Las normas de certificación del capítulo 4 de la ZIERDED solo entran en vigor en esa fecha -- confirme que la certificación de cualquier proveedor esté realmente vigente bajo el régimen antes de confiar en ella.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'es', 'Pruebe con antelación el canal de intercambio elegido, bien antes del 1 de enero de 2028', 'La obligación central de intercambio obligatorio se aplica desde esa fecha a prácticamente todas las entidades inscritas en el Registro Mercantil y a las personas autónomas, con multas reales bajo los art. 24/25 en caso de incumplimiento -- no deje las pruebas para el último momento antes de la fecha límite.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'Diario Oficial -- texto legal completo de la ZIERDED (Uradni list RS, št. 85/2025)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'UJP e-Racuni -- el portal de envío de facturas electrónicas del sector público (B2G)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'es', 'FURS -- Administración Financiera de Eslovenia' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 2;

-- ==================== de ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Zweistufiges System: eine seit Langem bestehende B2G-Pflicht über den zentralen Hub von UJP, ergänzt durch ein brandneues B2B-Gesetz (ZIERDED), das Ende 2025 erlassen wurde und mit einer zweistufigen Einführung 2027 und 2028 in Kraft tritt', 'Diese Analyseseite spiegelt das ZIERDED-Gesetz, wie es im slowenischen Amtsblatt veröffentlicht wurde, sowie öffentlich verfügbare behördliche Hinweise mit Stand Anfang August 2026 wider und dient allgemeinen Informationszwecken, nicht als Rechts- oder Steuerberatung. Bestätigen Sie aktuelle Anforderungen direkt bei FURS, UJP oder einem slowenischen Steuer-/Rechtsberater, bevor Sie sich bei Compliance-Entscheidungen auf diese Seite verlassen.', 'Der öffentliche Sektor Sloweniens verlangt seit dem 1. Januar 2015 elektronische Rechnungen gemäß ZOPSPU/ZOPSPU-A, geleitet über den zentralen EVIT-Hub von UJP. Für die B2B-E-Rechnungsstellung bestand bis 2025 keine allgemeine Pflicht, bis das Parlament die ZIERDED verabschiedete (veröffentlicht im Amtsblatt als Uradni list RS, št. 85/2025, vom 6. November 2025) -- Sloweniens erstes verpflichtendes Gesetz zur elektronischen Rechnungsstellung zwischen Unternehmen, mit einem Regime für zertifizierte E-Weg-Anbieter, das am 1. April 2027 in Kraft tritt, und der zentralen Austauschpflicht ab dem 1. Januar 2028.', 'Eine ZIERDED-konforme Rechnung wird über einen von drei zulässigen Kanälen ausgetauscht -- einen zertifizierten E-Weg-Anbieter ("e-pot"), eine direkte System-zu-System-Verbindung oder Peppol -- formatiert nach dem Standard e-SLOG 2.0, Sloweniens an EN 16931 angelehnter nationaler Spezifikation, die von der GZS (der Industrie- und Handelskammer) verwaltet wird. Dies ist ein dezentrales Austauschmodell, keine staatliche Freigabeplattform: Es gibt kein einziges verpflichtendes Regierungsportal für B2B-Rechnungen, wie es das e-Racuni-Portal von UJP für den öffentlichen Sektor darstellt.', 'Die B2B-Pflicht gilt universell -- für jede im slowenischen Handelsregister eingetragene Einheit und jede selbstständige Person, ohne Größenschwelle oder gestaffelte Ausnahme im Gesetzestext. Die B2G-Rechnungsstellung gilt bereits seit 2015 für den gesamten öffentlichen Sektor. Es handelt sich um eine tatsächlich neue B2B-Pflicht, nicht um die Erweiterung einer bestehenden -- die meisten slowenischen Unternehmen haben derzeit keine gesetzliche Pflicht, elektronische Rechnungen untereinander auszutauschen, und das ändert sich am 1. Januar 2028.', 'Die meisten Unternehmen, die dies lesen, haben derzeit keine B2B-E-Rechnungspflicht in Slowenien -- die anstehende Aufgabe besteht darin, rechtzeitig vor der Frist am 1. Januar 2028 einen der drei von der ZIERDED zugelassenen Austauschkanäle auszuwählen und zu testen, nicht darauf zu reagieren, dass bereits etwas in Kraft ist.', 'Die ZIERDED untermauert ihre B2B-Pflicht mit realen, artikelspezifischen Bußgeldern nach Art. 24 (Verstöße gegen den zentralen Austausch) sowie einem eigenen, niedrigeren Bußgeldrahmen nach Art. 25 für Verstöße bei Verbraucherrechnungen -- beide wurden in dieser Sitzung unabhängig anhand des Amtsblatttexts bestätigt, nicht aus einer Sekundärzusammenfassung übernommen.', 'Slowenien verlangt von öffentlichen Stellen seit dem 1. Januar 2015 den Empfang elektronischer Rechnungen (ZOPSPU/ZOPSPU-A, über den zentralen Hub von UJP). Ein neues Gesetz, die ZIERDED, führt Sloweniens erstes verpflichtendes B2B-E-Rechnungsregime ein: zertifizierte E-Weg-Anbieter ab dem 1. April 2027 und den verpflichtenden E-Rechnungsaustausch für praktisch alle Unternehmen und Selbstständigen ab dem 1. Januar 2028, unter Verwendung des Standards e-SLOG 2.0 über einen von drei zulässigen Kanälen einschließlich Peppol.', '🇸🇮' FROM countries WHERE code = 'SI';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2015', 'Öffentlicher Sektor muss elektronische Rechnungen empfangen (ZOPSPU/ZOPSPU-A)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 0;
