INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Apr. 2027', 'Regime für zertifizierte E-Weg-Anbieter tritt in Kraft' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1. Jan. 2028', 'Verpflichtender B2B-E-Rechnungsaustausch beginnt' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'de', '1.000-3.000 €', 'Zentraler Bußgeldrahmen nach Art. 24 für juristische Personen' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Format & Kanäle', '[["B2B-Rechnungsformat", "e-SLOG 2.0 -- Sloweniens eigener, an EN 16931 angelehnter XML-Standard, verwaltet von der GZS (Industrie- und Handelskammer)"], ["B2B-Austauschmodell", "Dezentral -- anders als bei der Rolle von UJP im B2G gibt es keine einzige verpflichtende staatliche Freigabeplattform für B2B"], ["Zulässige Kanäle (ZIERDED Art. 9)", "Zertifizierter E-Weg-Anbieter (\"e-pot\"); direkte System-zu-System-Verbindung; oder Peppol"], ["B2G-Rechnungsformat", "Ebenfalls e-SLOG, übermittelt über den EVIT-Hub von UJP (Banken, beauftragte Verarbeiter oder das e-Racuni-Portal)"]]', 'Die ZIERDED benennt kein einziges verpflichtendes Übertragungsnetz, wie es manche Länder mit CTC-Modell tun -- Unternehmen wählen unter den drei zulässigen Kanälen, sodass die Wahl des Anbieters in Slowenien wichtiger ist als in einem Regime mit einer einzigen Plattform.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Die Rolle von UJP im B2G', '[["EVIT-Hub", "UJP betreibt die \"enotna vstopna in izstopna točka\" (einheitliche Ein-/Ausgangsstelle) für den E-Rechnungsaustausch der Haushaltsnutzer"], ["e-Racuni-Portal", "Kostenlose Einreichungsmöglichkeit für Lieferanten ohne Bank oder beauftragten Verarbeiter -- https://eracuni.ujp.gov.si/"], ["Bank-/Verarbeiter-Wege", "Teilnehmende Banken und von UJP beauftragte Datenverarbeiter können ebenfalls E-Rechnungen an Haushaltsnutzer übermitteln"], ["Status als Peppol Authority", "Nicht bestätigt -- keine Quelle bestätigt, dass Slowenien über eine formell bei OpenPeppol registrierte Peppol Authority verfügt"]]', 'UJP wird gelegentlich informell als Sloweniens "Peppol Authority" bezeichnet -- dieser Titel taucht nicht auf der aktuellen eigenen Liste der Behörden von OpenPeppol auf, und die Regierungsseite von UJP beschreibt dessen Rolle als Betreiber des EVIT-Hubs, nicht als Peppol-Governance-Stelle. Betrachten Sie UJP als B2G-Hub, nicht als bestätigte Peppol Authority, bis eine Primärquelle etwas anderes belegt.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Wen die ZIERDED erfasst', '[["Anwendungsbereich (Art. 7)", "Jede im slowenischen Handelsregister eingetragene Einheit und jede selbstständige Person"], ["Größenschwelle", "Keine gefunden -- das Gesetz gilt einheitlich, ohne im Amtsblatttext identifizierte Ausnahme für Kleinunternehmen"], ["Verbraucherrechnungen", "Gesondert erfasst, unter dem niedrigeren Bußgeldrahmen nach Art. 25 statt Art. 24"], ["Öffentlicher Sektor (B2G)", "Bereits seit 2015 gesondert unter ZOPSPU/ZOPSPU-A erfasst -- die ZIERDED ist eine auf B2B fokussierte Ergänzung, kein Ersatz"]]', 'Art. 1 der ZIERDED verknüpft das Gesetz ausdrücklich mit der Umsetzung von Elementen der ViDA-Richtlinie der EU (2025/516) -- es ist zu erwarten, dass sich weitere Details (z. B. eine künftige digitale Meldepflicht) entwickeln, sobald der eigene Pfeiler von ViDA zu E-Rechnung/digitaler Meldung EU-weit bis 2030 schrittweise eingeführt wird.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', 'Die zweistufige Einführung', '[["1. April 2027", "Das Regime für zertifizierte E-Weg-Anbieter nach Kapitel 4 der ZIERDED tritt in Kraft -- Anbieter können die Zertifizierung beantragen, Unternehmen können zertifizierte Anbieter nutzen"], ["1. Januar 2028", "Die zentrale verpflichtende Austauschpflicht gilt für alle erfassten Einheiten, über alle drei zulässigen Kanäle"], ["Keine Registrierungspflicht vor 2027 gefunden", "Nichts im Amtsblatttext verlangt, dass Unternehmen sich vor dem Datum 2027 formell registrieren oder vorbereiten"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '⚠️ Verstöße gegen den zentralen Austausch (Art. 24)', NULL, NULL, 'Art. 24 der ZIERDED legt den zentralen Bußgeldrahmen für die Nichteinhaltung der verpflichtenden B2B-Austauschpflicht nach deren Inkrafttreten fest: 1.000-3.000 € für juristische Personen, 500-1.500 € für Einzelunternehmer und 100-500 € für eine verantwortliche Person innerhalb einer Organisation. Diese Zahlen wurden in dieser Sitzung durch direkten Abruf des Amtsblatttexts unabhängig bestätigt, nicht aus einer Sekundärquelle übernommen.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🧾 Verstöße bei Verbraucherrechnungen (Art. 25)', NULL, NULL, 'Für Verstöße bei Verbraucherrechnungen nach Art. 25 gilt ein eigener, niedrigerer Bußgeldrahmen: 500-1.500 € für juristische Personen, 100-500 € für Einzelunternehmer und 50-250 € für eine verantwortliche Person. Dies ist eine eigenständige Verstoßkategorie gegenüber den zentralen B2B-Austauschbußgeldern nach Art. 24, nicht eine alternative oder reduzierte Version derselben Strafe.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'de', '🔍 Was wir nicht bestätigen konnten', NULL, NULL, 'Die Bußgeldartikel der ZIERDED sind neues Recht -- es gibt noch keine Vollzugshistorie, auf die man sich berufen könnte, wie es die Analysen zu Costa Rica oder Jordanien können. Zwei nur auf Sekundärquellen beruhende Behauptungen, die gelegentlich über Sloweniens E-Rechnungs-Ökosystem wiederholt werden -- dass ZZI einen formell gebrandeten "Exchange Hub" betreibt und dass FURS ein in diesem Kontext nutzbares Tool namens "miniBlagajna" anbietet -- wurden in dieser Rechercherunde nicht unabhängig auf einer primären Regierungsseite bestätigt und werden auf dieser Seite absichtlich weggelassen, statt als Tatsache wiederholt zu werden.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Bestätigen Sie Ihren aktuellen B2G-E-Rechnungsweg, falls Sie an slowenische öffentliche Stellen verkaufen', 'Prüfen Sie, ob Ihr Unternehmen slowenische Haushaltsnutzer bereits über eine Bank, einen von UJP beauftragten Verarbeiter oder das e-Racuni-Portal von UJP erreicht -- diese Pflicht gilt bereits seit 2015 und ist vom neuen B2B-Gesetz unabhängig.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Lesen Sie den offiziellen Text der ZIERDED, bevor Sie einen B2B-Austauschkanal wählen', 'Das Gesetz erlaubt drei Kanäle -- einen zertifizierten E-Weg-Anbieter, eine direkte System-zu-System-Verbindung oder Peppol -- ohne eine einzige verpflichtende Plattform; verstehen Sie die Abwägungen, bevor Sie sich festlegen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Prüfen Sie, ob Ihre Rechnungssoftware e-SLOG-2.0-/EN-16931-konforme Ausgaben erzeugen kann', 'e-SLOG 2.0 ist Sloweniens nationaler Standard sowohl für die bestehende B2G-Pflicht als auch für das neue B2B-Gesetz -- bestätigen Sie, dass Ihr Anbieter diesen unterstützt, statt anzunehmen, dass allgemeine EN-16931-Unterstützung ausreicht.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Warten Sie bei der Wahl eines zertifizierten E-Weg-Anbieters das Zertifizierungsregime ab 1. April 2027 ab, bevor Sie einen auswählen', 'Die Zertifizierungsregeln nach Kapitel 4 der ZIERDED treten erst zu diesem Datum in Kraft -- bestätigen Sie, dass die Zertifizierung eines Anbieters unter dem Regime tatsächlich gilt, bevor Sie sich darauf verlassen.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'de', 'Testen Sie Ihren gewählten Austauschkanal rechtzeitig vor dem 1. Januar 2028', 'Die zentrale verpflichtende Austauschpflicht gilt ab diesem Datum für praktisch alle im Handelsregister eingetragenen Einheiten und Selbstständigen, mit realen Bußgeldern nach Art. 24/25 bei Nichteinhaltung -- verschieben Sie das Testen nicht bis zur Frist.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'Amtsblatt -- vollständiger Gesetzestext der ZIERDED (Uradni list RS, št. 85/2025)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'UJP e-Racuni -- das E-Rechnungs-Einreichungsportal des öffentlichen Sektors (B2G)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'de', 'FURS -- Slowenische Finanzverwaltung' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 2;

-- ==================== fr ====================

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Régime à deux niveaux : une obligation B2G de longue date via le hub central d''UJP, ainsi qu''une toute nouvelle loi B2B (ZIERDED) promulguée fin 2025, avec un déploiement en deux étapes aboutissant en 2027 et 2028', 'Cette page d''analyse reflète la loi ZIERDED telle que publiée au Journal officiel slovène ainsi que les indications publiques des autorités disponibles début août 2026, et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Confirmez les exigences actuelles directement auprès de FURS, d''UJP ou d''un conseiller fiscal/juridique slovène avant de fonder vos décisions de conformité sur cette page.', 'Le secteur public slovène exige des factures électroniques depuis le 1er janvier 2015 en vertu de la ZOPSPU/ZOPSPU-A, acheminées via le hub central EVIT d''UJP. La facturation électronique B2B n''a fait l''objet d''aucune obligation générale avant 2025, année où le parlement a adopté la ZIERDED (publiée au Journal officiel sous la référence Uradni list RS, št. 85/2025, du 6 novembre 2025) -- la première loi slovène rendant obligatoire la facturation électronique entre entreprises, avec un régime de prestataires de voie électronique certifiés prenant effet le 1er avril 2027 et l''obligation centrale d''échange à partir du 1er janvier 2028.', 'Une facture conforme à la ZIERDED est échangée via l''un des trois canaux autorisés -- un prestataire de voie électronique certifié (« e-pot »), une liaison directe système à système, ou Peppol -- au format de la norme e-SLOG 2.0, la spécification nationale slovène alignée sur la norme EN 16931 et gérée par la GZS (la Chambre de commerce et d''industrie). Il s''agit d''un modèle d''échange décentralisé, et non d''une plateforme de dédouanement gouvernementale : il n''existe pas de portail gouvernemental unique obligatoire pour les factures B2B, contrairement au rôle que joue le portail e-Racuni d''UJP pour le secteur public.', 'L''obligation B2B s''applique de manière universelle -- à toute entité inscrite au Registre du commerce slovène et à toute personne exerçant à titre indépendant, sans seuil de taille ni exception échelonnée identifiée dans le texte de la loi. La facturation B2G s''applique à l''ensemble du secteur public depuis 2015. Il s''agit d''une obligation B2B véritablement nouvelle, et non de l''extension d''une obligation existante -- la plupart des entreprises slovènes n''ont actuellement aucune obligation légale d''échanger des factures électroniques entre elles, ce qui changera le 1er janvier 2028.', 'La plupart des entreprises qui lisent cette page n''ont actuellement aucune obligation de facturation électronique B2B en Slovénie -- le travail à accomplir consiste à choisir et à tester l''un des trois canaux d''échange autorisés par la ZIERDED bien avant l''échéance du 1er janvier 2028, et non à réagir à une obligation déjà en vigueur.', 'La ZIERDED appuie son obligation B2B sur des sanctions réelles, propres à chaque article, prévues à l''art. 24 (infractions relatives à l''échange central) et sur une fourchette distincte et plus basse prévue à l''art. 25 pour les infractions relatives aux factures aux consommateurs -- toutes deux confirmées de façon indépendante par rapport au texte du Journal officiel au cours de cette session, et non reprises d''un résumé secondaire.', 'La Slovénie exige que les organismes du secteur public reçoivent des factures électroniques depuis le 1er janvier 2015 (ZOPSPU/ZOPSPU-A, via le hub central d''UJP). Une nouvelle loi, la ZIERDED, instaure le premier régime slovène de facturation électronique B2B obligatoire : des prestataires de voie électronique certifiés à partir du 1er avril 2027, et un échange obligatoire de factures électroniques pour la quasi-totalité des entreprises et des indépendants à partir du 1er janvier 2028, selon la norme e-SLOG 2.0, via l''un des trois canaux autorisés, dont Peppol.', '🇸🇮' FROM countries WHERE code = 'SI';

INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2015', 'Le secteur public est tenu de recevoir des factures électroniques (ZOPSPU/ZOPSPU-A)' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '6 nov. 2025', 'La ZIERDED -- première loi slovène de facturation électronique B2B -- est publiée au Journal officiel' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er avr. 2027', 'Le régime des prestataires de voie électronique certifiés prend effet' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1er janv. 2028', 'Début de l''échange obligatoire de factures électroniques B2B' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) SELECT s.id, 'fr', '1 000-3 000 €', 'Fourchette d''amende centrale de l''art. 24 pour les personnes morales' FROM deep_dive_stats s JOIN countries c ON s.country_id = c.id WHERE c.code = 'SI' AND s.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Format et canaux', '[["Format de facture B2B", "e-SLOG 2.0 -- la norme XML propre à la Slovénie, alignée sur EN 16931, gérée par la GZS (Chambre de commerce et d''industrie)"], ["Modèle d''échange B2B", "Décentralisé -- contrairement au rôle d''UJP en B2G, il n''existe pas de plateforme gouvernementale unique et obligatoire de dédouanement pour le B2B"], ["Canaux autorisés (ZIERDED, art. 9)", "Prestataire de voie électronique certifié (« e-pot ») ; liaison directe système à système ; ou Peppol"], ["Format de facture B2G", "Également e-SLOG, soumis via le hub EVIT d''UJP (banques, prestataires sous contrat, ou le portail e-Racuni)"]]', 'La ZIERDED ne désigne pas un réseau de transmission unique et obligatoire, contrairement à certains pays appliquant un modèle CTC -- les entreprises choisissent parmi les trois canaux autorisés, de sorte que le choix du prestataire compte davantage en Slovénie que dans un régime à plateforme unique.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'file_format' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Le rôle d''UJP dans le B2G', '[["Hub EVIT", "UJP exploite la « enotna vstopna in izstopna točka » (point d''entrée et de sortie unique) pour l''échange de factures électroniques des utilisateurs budgétaires"], ["Portail e-Racuni", "Voie de soumission gratuite pour les fournisseurs sans banque ni prestataire sous contrat -- https://eracuni.ujp.gov.si/"], ["Voies bancaires / prestataires", "Les banques participantes et les prestataires de traitement de données sous contrat avec UJP peuvent également acheminer des factures électroniques vers les utilisateurs budgétaires"], ["Statut de Peppol Authority", "Non établi -- aucune source ne confirme que la Slovénie dispose d''une Peppol Authority formellement enregistrée auprès d''OpenPeppol"]]', 'UJP est parfois décrite de manière informelle comme la « Peppol Authority » de la Slovénie -- ce titre ne figure pas dans la liste actuelle des autorités propre à OpenPeppol, et la page gouvernementale d''UJP décrit son rôle comme celui d''exploitant du hub EVIT, non comme un organisme de gouvernance Peppol. Considérez UJP comme le hub du B2G, et non comme une Peppol Authority confirmée, jusqu''à ce qu''une source primaire indique le contraire.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'file_format' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Qui est couvert par la ZIERDED', '[["Champ d''application (art. 7)", "Toute entité inscrite au Registre du commerce slovène, et toute personne exerçant à titre indépendant"], ["Seuil de taille", "Aucun identifié -- la loi s''applique uniformément, sans exception pour les petites entreprises identifiée dans le texte du Journal officiel"], ["Factures aux consommateurs", "Couvertes séparément, sous la fourchette de sanction plus basse de l''art. 25 plutôt que l''art. 24"], ["Secteur public (B2G)", "Déjà couvert séparément depuis 2015 en vertu de la ZOPSPU/ZOPSPU-A -- la ZIERDED est un ajout centré sur le B2B, non un remplacement"]]', 'L''art. 1 de la ZIERDED rattache explicitement la loi à la transposition d''éléments de la directive ViDA de l''UE (2025/516) -- il faut s''attendre à ce que davantage de détails (par exemple, toute future obligation de déclaration numérique) se précisent à mesure que le volet facturation électronique/déclaration numérique de ViDA se déploiera dans l''UE d''ici 2030.', NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'scope_transmission' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', 'Le déploiement en deux étapes', '[["1er avril 2027", "Le régime des prestataires de voie électronique certifiés du chapitre 4 de la ZIERDED prend effet -- les prestataires peuvent demander une certification et les entreprises peuvent commencer à recourir à des prestataires certifiés"], ["1er janvier 2028", "L''obligation centrale d''échange obligatoire s''applique à toutes les entités concernées, sur les trois canaux autorisés"], ["Aucune obligation d''inscription avant 2027 identifiée", "Rien dans le texte du Journal officiel n''oblige les entreprises à s''inscrire ou à se préparer formellement avant l''échéance de 2027"]]', NULL, NULL FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'scope_transmission' AND cd.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '⚠️ Infractions relatives à l''échange central (art. 24)', NULL, NULL, 'L''art. 24 de la ZIERDED fixe la fourchette de sanction centrale applicable en cas de non-respect de l''obligation d''échange B2B obligatoire, une fois celle-ci applicable : 1 000-3 000 € pour les personnes morales, 500-1 500 € pour les entrepreneurs individuels, et 100-500 € pour une personne responsable au sein d''une organisation. Ces montants ont été confirmés de manière indépendante par consultation directe du texte du Journal officiel au cours de cette session, et non repris d''une source secondaire.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🧾 Infractions relatives aux factures aux consommateurs (art. 25)', NULL, NULL, 'Une fourchette de sanction distincte et plus basse s''applique spécifiquement aux infractions relatives aux factures aux consommateurs en vertu de l''art. 25 : 500-1 500 € pour les personnes morales, 100-500 € pour les entrepreneurs individuels, et 50-250 € pour une personne responsable. Il s''agit d''une catégorie d''infraction distincte des amendes centrales pour l''échange B2B prévues à l''art. 24, et non d''une version alternative ou réduite de la même amende.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT cd.id, 'fr', '🔍 Ce que nous n''avons pas pu confirmer', NULL, NULL, 'Les articles de sanction de la ZIERDED relèvent d''une législation nouvelle -- il n''existe pas encore d''historique d''application auquel se référer, contrairement à ce que permettent les analyses consacrées au Costa Rica ou à la Jordanie. Deux affirmations reposant uniquement sur des sources secondaires, parfois répétées à propos de l''écosystème slovène de facturation électronique -- selon lesquelles ZZI exploiterait un « Exchange Hub » officiellement identifié comme tel, et selon lesquelles FURS proposerait un outil « miniBlagajna » utilisable dans ce contexte -- n''ont pas été corroborées de manière indépendante sur une page gouvernementale primaire au cours de cette phase de recherche, et sont délibérément omises de cette page plutôt que présentées comme des faits.' FROM deep_dive_cards cd JOIN countries c ON cd.country_id = c.id WHERE c.code = 'SI' AND cd.section = 'penalties_related' AND cd.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez votre voie B2G actuelle de facturation électronique, si vous vendez à des organismes publics slovènes', 'Vérifiez si votre entreprise atteint déjà les utilisateurs budgétaires slovènes par l''intermédiaire d''une banque, d''un prestataire sous contrat avec UJP, ou du portail e-Racuni d''UJP -- cette obligation s''applique depuis 2015 et est distincte de la nouvelle loi B2B.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Lisez le texte officiel de la ZIERDED avant de choisir un canal d''échange B2B', 'La loi autorise trois canaux -- un prestataire de voie électronique certifié, une liaison directe système à système, ou Peppol -- sans plateforme unique obligatoire ; comprenez les compromis avant de vous engager.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Vérifiez que votre logiciel de facturation peut produire des documents conformes à e-SLOG 2.0 / EN 16931', 'e-SLOG 2.0 est la norme nationale slovène tant pour l''obligation B2G existante que pour la nouvelle loi B2B -- vérifiez que votre prestataire la prend en charge, plutôt que de présumer qu''une prise en charge générique d''EN 16931 suffit.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Si vous optez pour un prestataire de voie électronique certifié, attendez le régime de certification du 1er avril 2027 avant d''en choisir un', 'Les règles de certification du chapitre 4 de la ZIERDED ne prennent effet qu''à cette date -- vérifiez que la certification de tout prestataire est effectivement en vigueur au titre du régime avant de vous y fier.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT sp.id, 'fr', 'Testez le canal d''échange choisi bien avant le 1er janvier 2028', 'L''obligation centrale d''échange obligatoire s''applique à compter de cette date à la quasi-totalité des entités inscrites au Registre du commerce et des indépendants, avec des amendes réelles en cas de non-conformité au titre des art. 24/25 -- ne remettez pas les tests à la dernière minute avant l''échéance.' FROM deep_dive_steps sp JOIN countries c ON sp.country_id = c.id WHERE c.code = 'SI' AND sp.sort_order = 4;

INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'Journal officiel -- texte juridique intégral de la ZIERDED (Uradni list RS, št. 85/2025)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'UJP e-Racuni -- le portail de soumission des factures électroniques du secteur public (B2G)' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_portal_translations (portal_id, lang, label) SELECT pt.id, 'fr', 'FURS -- Administration financière slovène' FROM deep_dive_portals pt JOIN countries c ON pt.country_id = c.id WHERE c.code = 'SI' AND pt.sort_order = 2;
